"""Small exact-gate/report from existing offline analysis, no raw reread."""
from pathlib import Path
import datetime,hashlib,json,re
R=Path(__file__).resolve().parent

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def new(p,x):assert not p.exists();p.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
def meta(p):return {'path':str(p),'relative':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'SHA':sha(p)}
def main():
    assert not (R/'INDEX.json').exists();d=json.loads((R/'attempts/001/output/RESULT.json').read_text(encoding='utf-8'));v=json.loads((R/'attempts/001/VALIDATION.json').read_text(encoding='utf-8'))
    for s in v['source_files']:assert sha(R/s['name'])==s['SHA']
